const DEFAULT_TO = 'owner@example.com';
const LATE_MINUTES = 120;
function rows(name) { return $(name).all().map(function (i) { return i.json; }); }
function sum(list, f) { return list.reduce(function (s, x) { return s + (Number(f(x)) || 0); }, 0); }
function r2(n) { return Math.round(n * 100) / 100; }
const orders = rows('Read orders').filter(function (o) { return o.Order_ID; });
const products = rows('Read products').filter(function (p) { return p.SKU; });
const invoices = rows('Read invoices').filter(function (i) { return i.Invoice_No; });
const dispatch = rows('Read dispatch').filter(function (d) { return d.Dispatch_ID; });
const payments = rows('Read payments for report').filter(function (p) { return p.Payment_ID; });
const moves = rows('Read movements for report').filter(function (m) { return m.Movement_ID; });
const today = $now.toFormat('yyyy-MM-dd');
const active = orders.filter(function (o) { return String(o.Status) !== 'Cancelled'; });
const todays = active.filter(function (o) { return String(o.Date).slice(0, 10) === today; });
const cancelledToday = orders.filter(function (o) { return String(o.Status) === 'Cancelled' && String(o.Date).slice(0, 10) === today; }).length;
const salesToday = sum(todays, function (o) { return o.Total; });
const collectionsToday = sum(payments.filter(function (p) { return String(p.Date).slice(0, 10) === today; }), function (p) { return p.Amount; });
const todayMoves = moves.filter(function (m) { return String(m.Time).slice(0, 10) === today; });
function movValue(types) { return r2(sum(todayMoves.filter(function (m) { return types.indexOf(String(m.Type)) >= 0; }), function (m) { return m.Value; })); }
const cogs = r2(-movValue(['SALE', 'CANCEL_RETURN', 'CUSTOMER_RETURN']));
const purchasesToday = movValue(['PURCHASE_RECEIPT']);
const adjustmentsToday = movValue(['ADJUST_UP', 'ADJUST_DOWN', 'SHRINKAGE']);
const marginToday = r2(salesToday - cogs);
const inventoryValue = r2(sum(products, function (p) { return Number(p.Stock) * Number(p.Cost); }));
const lowStock = products.filter(function (p) { return Number(p.Stock) < Number(p.Reorder_Level); }).map(function (p) { return { sku: p.SKU, name: p.Name, stock: Number(p.Stock), reorder_level: Number(p.Reorder_Level) }; });
const paidBy = {};
payments.forEach(function (p) { paidBy[String(p.Invoice_No)] = (paidBy[String(p.Invoice_No)] || 0) + (Number(p.Amount) || 0); });
const unpaid = invoices.filter(function (i) { return ['Unpaid', 'Partial'].indexOf(String(i.Status)) >= 0; }).map(function (i) {
  const balance = Math.max((Number(i.Amount) || 0) - (paidBy[String(i.Invoice_No)] || 0), 0);
  return { invoice_no: i.Invoice_No, order_id: i.Order_ID, amount: Number(i.Amount) || 0, balance: balance, due_date: String(i.Due_Date).slice(0, 10), overdue: String(i.Due_Date).slice(0, 10) < today, status: i.Status };
});
const receivable = r2(sum(unpaid, function (i) { return i.balance; }));
const refunds = invoices.filter(function (i) { return String(i.Status) === 'Refund pending'; }).map(function (i) { return { invoice_no: i.Invoice_No, order_id: i.Order_ID, amount: paidBy[String(i.Invoice_No)] || 0 }; });
const stuck = orders.filter(function (o) { return ['New', 'Invoiced'].indexOf(String(o.Status)) >= 0; }).map(function (o) { return o.Order_ID; });
const late = dispatch.filter(function (d) { return String(d.Status) === 'Dispatched'; }).map(function (d) {
  const t = DateTime.fromFormat(String(d.Dispatched_At), 'yyyy-MM-dd HH:mm:ss', { zone: $now.zoneName });
  const mins = t.isValid ? Math.round($now.diff(t, 'minutes').minutes) : 0;
  return { order_id: d.Order_ID, rider: d.Rider, minutes_out: mins };
}).filter(function (d) { return d.minutes_out > LATE_MINUTES; });
const waiting = orders.filter(function (o) { return String(o.Status) === 'Waiting for rider'; }).map(function (o) { return o.Order_ID; });
let recipient = DEFAULT_TO;
try { recipient = $('Recipient (form)').first().json.recipient || DEFAULT_TO; } catch (e) { recipient = DEFAULT_TO; }
const report = { date: today, orders_today: todays.length, cancelled_today: cancelledToday, sales_today: salesToday, collections_today: collectionsToday, cost_of_goods_sold_today: cogs, gross_margin_today: marginToday, purchases_today: purchasesToday, inventory_adjustments_today: adjustmentsToday, inventory_value: inventoryValue, low_stock: lowStock, unpaid_invoices: unpaid, accounts_receivable: receivable, refunds_pending: refunds, orders_stuck_without_dispatch: stuck, late_deliveries: late, late_after_minutes: LATE_MINUTES, orders_waiting_for_rider: waiting, currency: 'RD$' };
return [{ json: { recipient: recipient, subject: 'Demo Traders - Daily report ' + today, report: report } }];
